const canvas = document.getElementById('particles-canvas');
const ctx = canvas.getContext('2d');
let width, height;
function resize() {
width = window.innerWidth;
height = window.innerHeight;
canvas.width = width;
canvas.height = height;
}
window.addEventListener('resize', resize);
resize();
class Particle {
constructor() {
this.x = Math.random() * width;
this.y = Math.random() * height;
this.vx = (Math.random() - 0.5) * 0.8;
this.vy = (Math.random() - 0.5) * 0.8;
this.size = Math.random() * 2 + 1.5;
this.baseColor = 'rgba(255, 255, 255, ';
this.opacity = Math.random() * 0.2 + 0.8;
this.color = this.baseColor + this.opacity + ')';
}
update() {
this.x += this.vx;
this.y += this.vy;
if (this.x < 0 || this.x > width) this.vx *= -1;
if (this.y < 0 || this.y > height) this.vy *= -1;
let dx = mouse.x - this.x;
let dy = mouse.y - this.y;
let distance = Math.sqrt(dx * dx + dy * dy);
if (distance < 200) {
this.x -= dx * 0.01;
this.y -= dy * 0.01;
if (this.size < 5) this.size += 0.2;
} else {
if (this.size > 2.5) this.size -= 0.1;
}
}
draw() {
ctx.fillStyle = this.color;
ctx.shadowBlur = 15;
ctx.shadowColor = '#A7EBF2';
ctx.beginPath();
ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
ctx.fill();
ctx.shadowBlur = 0;
}
}
const particlesArray = [];
const numberOfParticles = window.innerWidth < 768 ? 50 : 150;
for (let i = 0; i < numberOfParticles; i++) {
particlesArray.push(new Particle());
}
let isScrolling;
let animationPaused = false;
window.addEventListener('scroll', () => {
if (window.innerWidth < 768) {
window.clearTimeout(isScrolling);
cancelAnimationFrame(animationId);
animationPaused = true;
isScrolling = setTimeout(() => {
animationPaused = false;
animate();
}, 150);
}
});
const mouse = { x: null, y: null };
window.addEventListener('mousemove', (e) => {
const rect = canvas.getBoundingClientRect();
mouse.x = e.clientX - rect.left;
mouse.y = e.clientY - rect.top;
});
let animationId;
function animate() {
if (animationPaused) return;
ctx.clearRect(0, 0, width, height);
for (let i = 0; i < particlesArray.length; i++) {
particlesArray[i].update();
particlesArray[i].draw();
for (let j = i; j < particlesArray.length; j++) {
let dx = particlesArray[i].x - particlesArray[j].x;
let dy = particlesArray[i].y - particlesArray[j].y;
let distance = Math.sqrt(dx * dx + dy * dy);
if (distance < 180) {
ctx.strokeStyle = 'rgba(167, 235, 242, ' + (1 - distance / 180) * 0.85 + ')';
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(particlesArray[i].x, particlesArray[i].y);
ctx.lineTo(particlesArray[j].x, particlesArray[j].y);
ctx.stroke();
}
}
}
animationId = requestAnimationFrame(animate);
}
animate();
function clearPack() {
const contactSection = document.getElementById('contact');
const packInput = document.getElementById('pack-input');
packInput.value = '';
setTimeout(() => {
packInput.style.borderColor = '';
packInput.style.boxShadow = '';
}, 100);
}
function selectPack(packName) {
const contactSection = document.getElementById('contact');
const packInput = document.getElementById('pack-input');
contactSection.scrollIntoView({ behavior: 'smooth' });
packInput.value = packName;
packInput.style.borderBottomColor = '#00FFFF';
packInput.style.boxShadow = '0 10px 30px rgba(0, 255, 255, 0.1)';
setTimeout(() => {
packInput.style.borderBottomColor = '';
packInput.style.boxShadow = '';
}, 3000);
}
function toggleMenu() {
const menu = document.getElementById('mobile-menu');
const hamburger = document.querySelector('.hamburger');
menu.classList.toggle('active');
hamburger.classList.toggle('active');
document.body.classList.toggle('menu-open');
}
function closeMenu() {
const menu = document.getElementById('mobile-menu');
const hamburger = document.querySelector('.hamburger');
menu.classList.remove('active');
hamburger.classList.remove('active');
document.body.classList.remove('menu-open');
}
document.addEventListener('click', (e) => {
const menu = document.getElementById('mobile-menu');
const hamburger = document.querySelector('.hamburger');
if (menu && !menu.contains(e.target) && !hamburger.contains(e.target)) {
closeMenu();
}
});
document.addEventListener("DOMContentLoaded", function() {
const modal = document.getElementById('inquiryModal');
window.openModal = function() {
modal.classList.add('active');
};
window.closeModal = function() {
modal.classList.remove('active');
};
if (modal) {
modal.addEventListener('click', function(e) {
if (e.target === this) closeModal();
});
}
var form = document.getElementById("luxuryForm");
if (form) {
form.addEventListener("submit", async function(event) {
event.preventDefault();
var status = document.getElementById("my-form-status");
var data = new FormData(event.target);
var btn = form.querySelector('button');
var originalText = btn.innerHTML;
btn.innerHTML = "Processing...";
btn.style.opacity = "0.7";
fetch(event.target.action, {
method: form.method,
body: data,
headers: {
'Accept': 'application/json'
}
}).then(response => {
if (response.ok) {
closeModal();
alert("Thank you. The concierge has received your request.");
form.reset();
} else {
response.json().then(data => {
if (Object.hasOwn(data, 'errors')) {
alert(data["errors"].map(error => error["message"]).join(", "));
} else {
alert("System busy. Please try again.");
}
});
}
}).catch(error => {
console.error("Engineer Debug:", error);
alert("SYSTEM ERROR: " + error.message);
}).finally(() => {
btn.innerHTML = originalText;
btn.style.opacity = "1";
});
});
console.log("Engineer Log: Form listener attached successfully.");
} else {
console.error("Engineer Error: Could not find form with id='luxuryForm'. Check your HTML!");
}
});
(function initArchiveReveal() {
const revealEls = document.querySelectorAll('.archive-reveal');
if (!revealEls.length) return;
const observer = new IntersectionObserver(function(entries) {
entries.forEach(function(entry) {
if (entry.isIntersecting) {
entry.target.classList.add('is-visible');
observer.unobserve(entry.target);
}
});
}, {
threshold: 0.15,
rootMargin: '0px 0px -50px 0px'
});
revealEls.forEach(function(el) {
observer.observe(el);
});
})();